  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this scheduling problem — are we minimizing the total completion time (makespan) of all three products, or is there another goal such as minimizing total flow time or meeting due dates?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting alternatives within one semantic question."
}

